//! C38 bounded GIF snapshots; no retained owner pointers.
use crate::{cpu::CpuContext,mem::{Mem,ConstPtr},native_batch_kernel::{self as k,Machine,Outcome}};
fn word(m:&Mem,a:u32)->Option<u32>{(a&3==0&&m.is_mapped_range(a,4)).then(||m.read(ConstPtr::<u32>::from_bits(a)))}
pub(crate)fn snapshot(m:&Mem,c:CpuContext,guard:(u32,u32))->Option<Machine>{
 let sp=c.regs[13];if sp&3!=0||c.cpsr&0x0600fc00!=0||!m.is_mapped_range(sp,0x870){return None;}let f=|o|word(m,sp+o);let width=m.read(ConstPtr::<i16>::from_bits(sp+0x148))as i32;let height=m.read(ConstPtr::<i16>::from_bits(sp+0x144))as i32;
 if !(1..=1024).contains(&width)||!(1..=4096).contains(&height)||f(0xa0)?!=sp+0xa8{return None;}
 let col=f(0xe4)?;let row=f(0xf4)?;if col>width as u32||row>=height as u32{return None;}let out=f(0xc0)?.checked_add(row.checked_mul(width as u32)?.checked_mul(4)?)?;if f(0xb8)?!=out.checked_add(col*4)?{return None;}
 let(input,remain,ip,dict,suffix,stack,top,palette)=(f(0xd0)?,f(0x100)?,f(0xbc)?,f(0xdc)?,f(0xc8)?,f(0xcc)?,f(0xc4)?,f(0x138)?);
 if remain>255||ip<input||ip.checked_add(remain)?>input.checked_add(256)?||top<stack||top>stack.checked_add(4097)?||f(0x140)?>256||f(0x140)?==0{return None;}
 let bits=f(0x104)?;let init=m.read(ConstPtr::<u8>::from_bits(sp+0xd8));let next=f(0x118)?;if !(2..=8).contains(&init)||!(3..=12).contains(&bits)||f(0x114)?>31||f(0x10c)?!=1u32<<init||f(0xfc)?!=(1u32<<init)+1||f(0x108)?!=(1u32<<bits)-1||next>(1<<12){return None;}
 if dict&1!=0||palette&3!=0||out&3!=0{return None;}let mut regions:Vec<k::Region>=Vec::new();for(a,n,w)in[(sp,0x870,true),(input,256,false),(dict,8192,true),(suffix,4096,true),(stack,4097,true),(palette,f(0x140)?*4,false),(out,width as u32*4,true)]{a.checked_add(n)?;if !m.is_mapped_range(a,n)||!k::disjoint(a,n,0x1000,0x3ff000)||guard.0!=0&&!k::disjoint(a,n,guard.0,guard.1.checked_sub(guard.0)?){return None;}for p in &regions{if !k::disjoint(a,n,p.address,p.bytes.len()as u32){return None;}}regions.push(k::region(a,m.bytes_at(ConstPtr::<u8>::from_bits(a),n),w));}
 Some(k::from_regions(c,regions,0))
}
pub(crate)fn calculate(m:Machine)->Option<Outcome>{crate::gif_island_generated::calculate(m)}

pub(crate)fn profitable(m:&Mem,c:CpuContext)->bool{let sp=c.regs[13];if sp&3!=0||!m.is_mapped_range(sp,0x870){return false;}let f=|o|word(m,sp+o).unwrap();let width=m.read(ConstPtr::<i16>::from_bits(sp+0x148))as i32;let col=f(0xe4);if width<32||col>width as u32||width as u32-col<32{return false;}let base=f(0xcc);let top=f(0xc4);(top>=base&&top-base>=32&&top-base<=4097)||f(0x100)>=64&&f(0x100)<=255}
pub(crate)fn seed(mem:&mut Mem,mut c:CpuContext,base:u32,n:u32)->CpuContext{use crate::mem::MutPtr;mem.bytes_at_mut(MutPtr::<u8>::from_bits(base),65536).fill(n as u8);let sp=base+4096;let(input,dict,suffix,stack,palette,out)=(base+8192,base+12288,base+24576,base+32768,base+40960,base+45056);let width=n%32+64;let put=|m:&mut Mem,a,v|m.write(MutPtr::<u32>::from_bits(a),v);for(o,v)in[(0xa0,sp+0xa8),(0xb8,out),(0xc0,out),(0xe4,0),(0xf4,0),(0xd0,input),(0x100,0),(0xbc,input),(0xdc,dict),(0xc8,suffix),(0xcc,stack),(0xc4,stack),(0x138,palette),(0x140,256),(0x104,9),(0x114,0),(0x10c,256),(0xfc,257),(0x108,511),(0x118,258),(0xf0,u32::MAX),(0xe0,0),(0x19c,u32::MAX)]{put(mem,sp+o,v);}mem.write(MutPtr::<u16>::from_bits(sp+0x148),width as u16);mem.write(MutPtr::<u16>::from_bits(sp+0x144),1);mem.write(MutPtr::<u8>::from_bits(sp+0xd8),8);for i in 0..4096{mem.write(MutPtr::<u16>::from_bits(dict+i*2),if i<256{0}else{(i-1)as u16});mem.write(MutPtr::<u8>::from_bits(suffix+i),i as u8);}for i in 0..256{put(mem,palette+i*4,0xff000000|i*0x010101);}if n%2==0{put(mem,sp+0xc4,stack+width);for i in 0..width{mem.write(MutPtr::<u8>::from_bits(stack+i),(i+n)as u8);}}else{let mut v=0u32;let mut bits=0;let mut bytes=Vec::new();for i in 0..width{for x in [256,(i+n)%256]{v|=x<<bits;bits+=9;while bits>=8{bytes.push(v as u8);v>>=8;bits-=8;}}}if bits>0{bytes.push(v as u8);}mem.bytes_at_mut(MutPtr::<u8>::from_bits(input),bytes.len()as u32).copy_from_slice(&bytes);put(mem,sp+0x100,bytes.len()as u32);}c.regs[13]=sp;c.regs[15]=crate::gif_island_generated::ENTRY;c.cpsr=(c.cpsr&0x0fffffff)|((n&15)<<28)|0x20;c}
